import React, { useState } from 'react';
import { Code, X, Edit3, Trash2, Check, Terminal, Film } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const SAMPLE_DATA: Record<string, ScrollSection[]> = {
  '1': [
    { title: "THE DREAM", description: "A voyage through the mechanical subconscious.", triggerTime: 0.15, alignment: 'center', vibe: 'cinematic' },
    { title: "SYNCHRONY", description: "Parts moving in a beautiful, unintended dance.", triggerTime: 0.35, alignment: 'left', vibe: 'cinematic' },
    { title: "NIGHTFALL", description: "Shadows defining the edges of the digital void.", triggerTime: 0.55, alignment: 'right', vibe: 'cinematic' },
    { title: "SYSTEMS", description: "Every gear turning with absolute purpose.", triggerTime: 0.75, alignment: 'center', vibe: 'cinematic' },
    { title: "INFINITY", description: "The loop continues beyond the frame.", triggerTime: 0.90, alignment: 'center', vibe: 'cinematic' }
  ]
};

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08,
    scrollDepth: 6,
    startOffset: 0.05,
    endOffset: 0.05,
    viewportAnchor: 0.1,
    widthMode: 'full',
    maxWidth: '1200px',
    topSpacer: 0,
    bottomSpacer: 100
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleVideoInit = async (url: string, sourceName: string, sampleId?: string) => {
    const localData = sampleId ? SAMPLE_DATA[sampleId] : null;
    if (localData) {
      setState(prev => ({ ...prev, url, sections: localData, isAnalyzing: false }));
      return;
    }
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    try {
      const storySections = await generateVideoStory(`Source: ${sourceName}`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err) {
      setState(prev => ({ ...prev, sections: [], isAnalyzing: false }));
    }
  };

  if (state.url && !state.isAnalyzing) {
    return (
      <div className="bg-[#000000] text-white min-h-screen selection:bg-indigo-500/50">
        <nav className="fixed top-4 md:top-6 left-1/2 -translate-x-1/2 w-[95%] md:w-[90%] max-w-5xl z-[200] px-4 md:px-6 py-3 md:py-4 flex justify-between items-center bg-black/60 backdrop-blur-3xl border border-indigo-500/10 rounded-2xl shadow-[0_20px_60px_rgba(0,0,0,0.8)]">
          <div className="flex items-center gap-4">
            <InfinityLogo size={20} className="text-indigo-500 drop-shadow-[0_0_15px_rgba(99,102,241,0.5)]" />
            <div className="flex items-baseline gap-3">
              <span className="text-[11px] md:text-[12px] font-black tracking-[0.5em] uppercase text-indigo-100 leading-none">INFINITY</span>
              <span className="hidden sm:inline text-[9px] font-bold tracking-[0.2em] uppercase text-indigo-500/60">/ NARRATIVE</span>
            </div>
          </div>

          <div className="flex items-center gap-2 md:gap-3">
            <button 
              onClick={() => setIsEditMode(!isEditMode)}
              className={`flex items-center gap-2 px-3 md:px-4 py-2 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-widest transition-all border ${isEditMode ? 'bg-indigo-600 border-indigo-500 text-white shadow-[0_0_20px_rgba(79,70,229,0.4)]' : 'bg-indigo-950/20 border-indigo-500/20 text-indigo-500 hover:text-indigo-300 hover:bg-indigo-900/30'}`}
            >
              {isEditMode ? <Check size={12} /> : <Edit3 size={12} />}
              <span>{isEditMode ? 'Done' : 'Edit'}</span>
            </button>
            <div className="w-[1px] h-4 bg-indigo-500/20 mx-1" />
            <button 
              onClick={() => setShowExportModal(true)} 
              className="flex items-center gap-2 px-4 md:px-5 py-2.5 bg-indigo-600/10 border border-indigo-500/20 text-indigo-400 rounded-xl text-[8px] md:text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all active:scale-95 shadow-xl"
            >
              <Terminal size={12} /> <span>Code</span>
            </button>
            <button onClick={() => setState({ ...state, url: null })} className="p-2 text-indigo-500/20 hover:text-red-500 transition-colors">
              <Trash2 size={16} />
            </button>
          </div>
        </nav>

        <div className="transition-all duration-700">
          <VideoScroller 
            videoUrl={state.url!} 
            sections={state.sections} 
            isEditMode={isEditMode}
            onUpdateSection={(idx, updated) => {
              const next = [...state.sections];
              next[idx] = updated;
              setState(prev => ({ ...prev, sections: next }));
            }}
          />
        </div>

        {showExportModal && (
          <div className="fixed inset-0 z-[1000] bg-black/95 flex items-center justify-center p-4 md:p-6 animate-in fade-in duration-300 backdrop-blur-3xl">
            <div className="bg-[#050507] border border-indigo-500/10 rounded-[2.5rem] w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden shadow-[0_40px_100px_rgba(0,0,0,0.9)]">
              <div className="px-6 md:px-8 py-5 md:py-7 border-b border-indigo-500/5 flex justify-between items-center bg-black/40">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-indigo-500/10 rounded-xl flex items-center justify-center text-indigo-500">
                    <Code size={20} />
                  </div>
                  <h3 className="text-[10px] md:text-[11px] font-black tracking-widest uppercase text-indigo-100">Implementation Export</h3>
                </div>
                <button onClick={() => setShowExportModal(false)} className="p-3 hover:bg-indigo-500/10 rounded-full text-indigo-500/40 transition-colors"><X size={20}/></button>
              </div>
              <div className="flex-1 p-6 md:p-8 overflow-y-auto font-mono text-[9px] md:text-[11px] text-indigo-400/60 bg-black/60 leading-relaxed scrollbar-none border-y border-indigo-500/5">
                <pre className="whitespace-pre-wrap">{generateSnippetCode(state.sections, state.url!, state.sensitivity, state.scrollDepth, state.startOffset, state.endOffset, state.viewportAnchor, state.widthMode, state.maxWidth)}</pre>
              </div>
              <div className="px-6 md:px-8 py-6 md:py-8 flex justify-center bg-black/40">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(generateSnippetCode(state.sections, state.url!, state.sensitivity, state.scrollDepth, state.startOffset, state.endOffset, state.viewportAnchor, state.widthMode, state.maxWidth));
                    setCopied(true);
                    setTimeout(() => setCopied(false), 2000);
                  }}
                  className={`w-full md:w-auto px-12 py-4 rounded-2xl font-black uppercase text-[10px] md:text-[11px] tracking-[0.2em] transition-all transform active:scale-95 ${copied ? 'bg-emerald-600 text-white' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-[0_0_40px_rgba(79,70,229,0.3)]'}`}
                >
                  {copied ? 'Copied' : 'Copy Code Snippet'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-transparent text-white relative flex flex-col items-center justify-center p-6 overflow-hidden">
      <header className="fixed top-10 md:top-14 left-10 md:left-14 z-50 flex items-center gap-8 animate-in slide-in-from-left-4 duration-1000">
        <div className="flex items-center gap-5">
          <InfinityLogo size={32} className="text-indigo-500 drop-shadow-[0_0_25px_rgba(99,102,241,0.7)]" />
          <span className="text-lg md:text-xl font-black tracking-[0.6em] uppercase text-indigo-50 lead-none">INFINITY</span>
        </div>
        <div className="hidden md:block w-[1px] h-10 bg-indigo-500/20" />
        <span className="hidden md:block text-[11px] font-black tracking-[0.4em] uppercase text-indigo-500/60 drop-shadow-[0_0_15px_rgba(99,102,241,0.3)]">AEON STUDIO</span>
      </header>

      <main className="relative z-10 w-full max-w-7xl pt-24 md:pt-48 pb-12">
        <div className="text-center mb-16 md:mb-32 space-y-8 md:space-y-12 animate-in fade-in slide-in-from-bottom-12 duration-1000 delay-200">
          <h1 className="text-6xl md:text-[12rem] font-black tracking-tight leading-[0.7] text-white">
            NARRATIVE<br />
            <span className="text-indigo-600 drop-shadow-[0_0_80px_rgba(79,70,229,0.4)] tracking-[-0.05em]">ENGINE.</span>
          </h1>
          <p className="max-w-xs md:max-w-2xl mx-auto text-indigo-500/40 text-[11px] md:text-sm font-semibold leading-relaxed tracking-[0.5em] uppercase">Scroll-synchronized storytelling for the next era of digital architecture.</p>
        </div>

        <div className="w-full max-w-4xl mx-auto bg-[#050507]/60 border border-indigo-500/10 p-8 md:p-14 rounded-[3rem] md:rounded-[4rem] backdrop-blur-[120px] shadow-[0_60px_150px_rgba(0,0,0,0.9)] animate-in zoom-in-95 duration-1000 delay-500">
          <FileUpload onFileSelect={(file) => handleVideoInit(URL.createObjectURL(file), file.name)} onSampleSelect={(url, name, id) => handleVideoInit(url, name, id)} isAnalyzing={state.isAnalyzing} />
        </div>
      </main>
    </div>
  );
};

export default App;

