import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const SAMPLE_DATA: Record<string, ScrollSection[]> = {
  '1': [
    { title: "THE DREAM", description: "A voyage through the mechanical subconscious.", triggerTime: 0.15, alignment: 'center', vibe: 'cinematic' },
    { title: "SYNCHRONY", description: "Parts moving in a beautiful, unintended dance.", triggerTime: 0.35, alignment: 'left', vibe: 'cinematic' },
    { title: "NIGHTFALL", description: "Shadows defining the edges of the digital void.", triggerTime: 0.55, alignment: 'right', vibe: 'cinematic' },
    { title: "SYSTEMS", description: "Every gear turning with absolute purpose.", triggerTime: 0.75, alignment: 'center', vibe: 'cinematic' },
    { title: "INFINITY", description: "The loop continues beyond the frame.", triggerTime: 0.90, alignment: 'center', vibe: 'cinematic' }
  ]
};

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08,
    scrollDepth: 6,
    startOffset: 0.05,
    endOffset: 0.05,
    viewportAnchor: 0.1,
    widthMode: 'full',
    maxWidth: '1200px',
    topSpacer: 0,
    bottomSpacer: 100
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleVideoInit = async (url: string, sourceName: string, sampleId?: string) => {
    const localData = sampleId ? SAMPLE_DATA[sampleId] : null;
    if (localData) {
      setState(prev => ({ ...prev, url, sections: localData, isAnalyzing: false }));
      return;
    }
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    try {
      const storySections = await generateVideoStory(`Source: ${sourceName}`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err) {
      setState(prev => ({ ...prev, sections: [], isAnalyzing: false }));
    }
  };

  if (state.url && !state.isAnalyzing) {
    return (
      <div className="bg-black text-white min-h-screen selection:bg-indigo-500/50">
        <nav className="fixed top-6 left-1/2 -translate-x-1/2 w-[90%] max-w-5xl z-[200] px-6 py-4 flex justify-between items-center bg-black/60 backdrop-blur-3xl border border-white/10 rounded-2xl shadow-[0_20px_60px_rgba(0,0,0,0.8)]">
          <div className="flex items-center gap-4">
            <InfinityLogo size={20} className="text-indigo-500" />
            <div className="flex flex-col">
              <span className="text-[10px] font-black tracking-[0.3em] uppercase text-white leading-tight">AEON</span>
              <span className="text-[7px] font-bold tracking-[0.2em] uppercase text-indigo-500/60">INFINITY ENGINE</span>
            </div>
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setIsEditMode(!isEditMode)}
              className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all border ${isEditMode ? 'bg-indigo-600 border-indigo-500 text-white' : 'bg-white/5 border-white/10 text-white/60 hover:text-white hover:bg-white/10'}`}
            >
              {isEditMode ? <Check size={12} /> : <Edit3 size={12} />}
              <span>{isEditMode ? 'Done' : 'Edit'}</span>
            </button>
            <button 
              onClick={() => setShowExportModal(true)} 
              className="flex items-center gap-2 px-5 py-2.5 bg-indigo-600/10 border border-indigo-500/20 text-indigo-400 rounded-xl text-[9px] font-black uppercase tracking-widest hover:bg-indigo-600 hover:text-white transition-all shadow-xl"
            >
              <Terminal size={12} /> <span>Code</span>
            </button>
            <button onClick={() => setState({ ...state, url: null })} className="p-2 text-white/20 hover:text-red-500 transition-colors">
              <Trash2 size={16} />
            </button>
          </div>
        </nav>

        <div className="transition-all duration-700">
          <VideoScroller 
            videoUrl={state.url!} 
            sections={state.sections} 
            isEditMode={isEditMode}
            onUpdateSection={(idx, updated) => {
              const next = [...state.sections];
              next[idx] = updated;
              setState(prev => ({ ...prev, sections: next }));
            }}
          />
        </div>

        {showExportModal && (
          <div className="fixed inset-0 z-[1000] bg-black/95 flex items-center justify-center p-6 animate-in fade-in duration-300 backdrop-blur-3xl">
            <div className="bg-[#050507] border border-white/5 rounded-[2.5rem] w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden shadow-2xl">
              <div className="px-8 py-7 border-b border-white/5 flex justify-between items-center bg-black/40">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 bg-indigo-500/10 rounded-xl flex items-center justify-center text-indigo-500">
                    <Code size={20} />
                  </div>
                  <h3 className="text-[11px] font-black tracking-widest uppercase text-white">Implementation Export</h3>
                </div>
                <button onClick={() => setShowExportModal(false)} className="p-3 hover:bg-white/10 rounded-full text-white/40 transition-colors"><X size={20}/></button>
              </div>
              <div className="flex-1 p-8 overflow-y-auto font-mono text-[11px] text-white/40 bg-black/60 leading-relaxed scrollbar-none">
                <pre className="whitespace-pre-wrap">{generateSnippetCode(state.sections, state.url!, state.sensitivity, state.scrollDepth, state.startOffset, state.endOffset, state.viewportAnchor, state.widthMode, state.maxWidth)}</pre>
              </div>
              <div className="px-8 py-8 flex justify-center bg-black/40 border-t border-white/5">
                <button 
                  onClick={() => {
                    navigator.clipboard.writeText(generateSnippetCode(state.sections, state.url!, state.sensitivity, state.scrollDepth, state.startOffset, state.endOffset, state.viewportAnchor, state.widthMode, state.maxWidth));
                    setCopied(true);
                    setTimeout(() => setCopied(false), 2000);
                  }}
                  className={`w-full md:w-auto px-12 py-4 rounded-2xl font-black uppercase text-[11px] tracking-[0.2em] transition-all transform active:scale-95 ${copied ? 'bg-emerald-600 text-white' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-[0_0_40px_rgba(79,70,229,0.3)]'}`}
                >
                  {copied ? 'Copied' : 'Copy Code Snippet'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-black text-white relative flex flex-col items-center p-6 pt-12">
      {/* Background Glow */}
      <div className="fixed inset-0 pointer-events-none overflow-hidden">
        <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[800px] h-[800px] bg-indigo-600/10 rounded-full blur-[160px]" />
      </div>

      <header className="w-full max-w-7xl flex items-center justify-start z-50 animate-in slide-in-from-top-4 duration-1000">
        <div className="flex items-center gap-4">
          <InfinityLogo size={28} className="text-indigo-500" />
          <div className="flex flex-col">
            <span className="text-[12px] md:text-[14px] font-black tracking-[0.4em] uppercase text-white leading-tight">AEON</span>
            <span className="text-[8px] md:text-[10px] font-bold tracking-[0.2em] uppercase text-white/40">INFINITY ENGINE</span>
          </div>
        </div>
      </header>

      <main className="relative z-10 w-full max-w-6xl pt-20 md:pt-32 flex flex-col items-center">
        {/* Badge */}
        <div className="mb-10 animate-in fade-in zoom-in duration-1000 delay-100">
           <div className="px-6 py-2 bg-indigo-900/10 border border-indigo-500/20 rounded-full text-[9px] font-black tracking-[0.3em] uppercase text-indigo-400 backdrop-blur-sm">
             Cinematic Scroll Pro
           </div>
