        {/* Hero Headlines */}
        <div className="text-center mb-16 md:mb-24 space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-1000 delay-200">
          <h1 className="text-6xl md:text-[9.5rem] font-black tracking-[-0.04em] leading-[0.85] text-white">
            NARRATIVE<br />
            <span className="bg-gradient-to-r from-indigo-500 to-blue-400 bg-clip-text text-transparent drop-shadow-[0_0_60px_rgba(79,70,229,0.5)]">STRUCTURE.</span>
