import { ScrollSection } from "../types";

/**
 * AEON UNIVERSAL NARRATIVE EXPORT v24.0
 * Generates high-performance, self-contained interactive components.
 */
export function generateSnippetCode(
  sections: ScrollSection[], 
  videoUrl: string, 
  sensitivity: number = 0.08, 
  scrollDepth: number = 6,
  startOffset: number = 0.05,
  endOffset: number = 0.05,
  viewportAnchor: number = 0.1,
  widthMode: 'full' | 'boxed' = 'full',
  maxWidth: string = '1200px',
  layoutMode: 'section' | 'background' = 'section'
): string {
  const isBlob = videoUrl.startsWith('blob:');
  const displayUrl = isBlob ? 'https://YOUR_DOMAIN.com/path/to/video.mp4' : videoUrl;
  const sectionsJSON = JSON.stringify(sections, null, 2);
  const instanceId = 'aeon-' + Math.random().toString(36).substr(2, 9);

  const containerStyles = widthMode === 'boxed' 
    ? `max-width: ${maxWidth}; margin: 0 auto; border-radius: 40px; overflow: hidden;` 
    : `width: 100%; margin: 0;`;

  if (layoutMode === 'background') {
    return `
<!-- 
  =============================================================================
  AEON // GLOBAL BACKGROUND NARRATIVE - QUICK START GUIDE
  =============================================================================

  HOW TO USE THIS CODE:
  1. OPEN: Your website's main HTML file.
  2. PASTE: Place this entire block IMMEDIATELY after your opening <body> tag.
  3. VIDEO SOURCE: Currently set to a placeholder or local blob. 
     Update the 'src' in the CONFIG script (bottom of this code) to your 
     hosted .mp4 URL for it to work on your live site.

  WHAT THIS DOES:
  - This module creates a FIXED background layer (z-index: -1).
  - It listens to the ENTIRE page scroll, not just one section.
  - Your existing website content (text, buttons, etc.) will float 
    naturally on top of this video.
  =============================================================================
-->
<div id="${instanceId}-global-bg" style="position: fixed; inset: 0; width: 100%; height: 100%; z-index: -1; background: #000; overflow: hidden; pointer-events: none;">
    <style>
        #${instanceId}-global-bg .aeon-video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; opacity: 0; transition: opacity 1.5s ease; }
        #${instanceId}-global-bg .aeon-overlay { position: absolute; inset: 0; z-index: 2; background: radial-gradient(circle at 50% 50%, rgba(0,0,0,0) 0%, rgba(0,0,0,0.6) 100%); }
        #${instanceId}-global-bg .aeon-node { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; opacity: 0; visibility: hidden; padding: 20px; box-sizing: border-box; }
        #${instanceId}-global-bg .aeon-title { color: white; font-family: sans-serif; font-weight: 900; font-size: clamp(2rem, 8vw, 10rem); text-transform: uppercase; margin: 0; text-align: center; line-height: 0.85; letter-spacing: -0.04em; }
        #${instanceId}-global-bg .aeon-desc { color: rgba(255,255,255,0.4); font-family: sans-serif; font-weight: 700; font-size: 14px; text-transform: uppercase; letter-spacing: 0.5em; margin-top: 30px; text-align: center; max-width: 600px; }
    </style>
    <video id="${instanceId}-v" class="aeon-video" playsinline muted preload="auto"></video>
    <div class="aeon-overlay" id="${instanceId}-stage"></div>
    <script>
        (function() {
            /* --- NARRATIVE CONFIGURATION --- */
            const CONFIG = { 
                src: "${displayUrl}", // <-- UPDATE THIS TO YOUR HOSTED VIDEO URL
                data: ${sectionsJSON}, 
                lerp: ${sensitivity} 
            };

            const video = document.getElementById('${instanceId}-v');
            const stage = document.getElementById('${instanceId}-stage');
            video.src = CONFIG.src;

            // Build Narrative Nodes
            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-node'; node.id = '${instanceId}-n-' + i;
                node.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0, currentProgress = 0, isSeeking = false;

            function update() {
                // Smooth Smoothing (LERP)
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;

                // Sync Video Time
                if (video.duration && !isSeeking) {
                    const targetTime = (video.duration - 0.05) * currentProgress;
                    if (Math.abs(video.currentTime - targetTime) > 0.03) { 
                        isSeeking = true; 
                        video.currentTime = targetTime; 
                    }
                }

                // Sync Text Animations
                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById('${instanceId}-n-' + i);
                    const dist = Math.abs(currentProgress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.12));
                    el.style.opacity = opacity; 
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(currentProgress - s.triggerTime) * 100}px, 0)\`;
                });
                requestAnimationFrame(update);
            }

            // Track Global Body Scroll
            window.addEventListener('scroll', () => {
                const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
                targetProgress = window.scrollY / (totalHeight || 1);
            }, { passive: true });

            video.onseeked = () => isSeeking = false;
            video.onloadedmetadata = () => { video.style.opacity = '1'; update(); };
            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>
    `;
  }

  // DEFAULT SECTION TRACK EXPORT
  return `
<!-- 
  =============================================================================
  AEON // STANDALONE NARRATIVE SECTION - QUICK START GUIDE
  =============================================================================

  HOW TO USE THIS CODE:
  1. OPEN: Your website's HTML file.
  2. PASTE: Place this code block wherever you want the video section to appear 
     (e.g., between your Hero section and your Footer).
  3. VIDEO SOURCE: Currently set to a placeholder or local blob. 
     Update the 'src' in the CONFIG script (bottom of this code) to your 
     hosted .mp4 URL for it to work on your live site.

  WHAT THIS DOES:
  - Creates a "Scroll Track" that is ${scrollDepth}x the height of the screen.
  - The video stays "Sticky" as you scroll through this specific segment.
  =============================================================================
-->
<div id="${instanceId}-track" style="height: ${scrollDepth * 100}vh; position: relative; background: #000; overflow: visible; ${containerStyles}">
    <style>
        #${instanceId}-track { font-family: sans-serif; background: #000; }
        #${instanceId}-track .aeon-stage { position: sticky; top: 0; left: 0; width: 100%; height: 100vh; overflow: hidden; display: flex; align-items: center; justify-content: center; }
        #${instanceId}-track .aeon-video { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; z-index: 1; opacity: 0; transition: opacity 1.2s ease; }
        #${instanceId}-track .aeon-overlay { position: absolute; inset: 0; z-index: 2; display: flex; align-items: center; justify-content: center; pointer-events: none; background: linear-gradient(to bottom, rgba(0,0,0,1) 0%, rgba(0,0,0,0) 20%, rgba(0,0,0,0) 80%, rgba(0,0,0,1) 100%); }
        #${instanceId}-track .aeon-node { position: absolute; width: 100%; padding: 0 10%; opacity: 0; visibility: hidden; box-sizing: border-box; }
        #${instanceId}-track .aeon-title { font-size: clamp(2.5rem, 10vw, 8.5rem); font-weight: 900; text-transform: uppercase; line-height: 0.85; color: white; margin: 0; letter-spacing: -0.04em; }
        #${instanceId}-track .aeon-desc { font-size: 14px; font-weight: 700; text-transform: uppercase; color: rgba(255,255,255,0.4); margin-top: 2rem; letter-spacing: 0.4em; }
    </style>
    <div class="aeon-stage">
        <video id="${instanceId}-v" class="aeon-video" playsinline muted preload="auto"></video>
        <div id="${instanceId}-g" class="aeon-overlay"></div>
    </div>
    <script>
        (function() {
            /* --- NARRATIVE CONFIGURATION --- */
            const CONFIG = { 
                src: "${displayUrl}", // <-- UPDATE THIS TO YOUR HOSTED VIDEO URL
                data: ${sectionsJSON}, 
                lerp: ${sensitivity}, 
                id: "${instanceId}",
                viewportAnchor: ${viewportAnchor} 
            };

            const track = document.getElementById(CONFIG.id + '-track');
            const video = document.getElementById(CONFIG.id + '-v');
            const stage = document.getElementById(CONFIG.id + '-g');
            video.src = CONFIG.src;

            // Build Narrative Nodes
            CONFIG.data.forEach((s, i) => {
                const node = document.createElement('div');
                node.className = 'aeon-node'; node.id = CONFIG.id + '-n-' + i;
                node.style.textAlign = s.alignment;
                node.innerHTML = \`<h2 class="aeon-title">\${s.title}</h2><p class="aeon-desc">\${s.description}</p>\`;
                stage.appendChild(node);
            });

            let targetProgress = 0, currentProgress = 0, isSeeking = false;

            function update() {
                currentProgress += (targetProgress - currentProgress) * CONFIG.lerp;
                const progress = currentProgress;

                if (video.duration && !isSeeking) {
                    const targetTime = (video.duration - 0.05) * progress;
                    if (Math.abs(video.currentTime - targetTime) > 0.03) { 
                        isSeeking = true; 
                        video.currentTime = targetTime; 
                    }
                }

                CONFIG.data.forEach((s, i) => {
                    const el = document.getElementById(CONFIG.id + '-n-' + i);
                    const dist = Math.abs(progress - s.triggerTime);
                    const opacity = Math.max(0, 1 - (dist / 0.12));
                    el.style.opacity = opacity; 
                    el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
                    el.style.transform = \`translate3d(0, \${(progress - s.triggerTime) * 100}px, 0)\`;
                });
                requestAnimationFrame(update);
            }

            // Track local section scroll
            window.addEventListener('scroll', () => {
                const rect = track.getBoundingClientRect();
                const totalHeight = track.offsetHeight - window.innerHeight;
                if (totalHeight > 0) {
                    targetProgress = Math.max(0, Math.min(1, ((window.innerHeight * CONFIG.viewportAnchor) - rect.top) / totalHeight));
                }
            }, { passive: true });

            video.onseeked = () => isSeeking = false;
            video.onloadedmetadata = () => { video.style.opacity = '1'; update(); };
            if (video.readyState >= 2) video.onloadedmetadata();
        })();
    </script>
</div>
`;
}

