import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
  layoutMode?: 'section' | 'background';
  scrollDepth: number;
  sensitivity: number;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  onUpdateSection, 
  isEditMode,
  layoutMode = 'section',
  scrollDepth,
  sensitivity
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  const LERP_FRICTION = sensitivity; 
  const VIEWPORT_ANCHOR = 0.1;

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;
    setIsLoaded(false);
    video.src = videoUrl;
    video.load();
    video.onloadedmetadata = () => { 
      setIsLoaded(true); 
      video.currentTime = 0; 
    };
  }, [videoUrl]);

  useEffect(() => {
    let rafId: number;

    const handleScroll = () => {
      if (layoutMode === 'background') {
        const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
        const progress = window.scrollY / (totalHeight || 1);
        targetProgress.current = Math.max(0, Math.min(1, progress));
        return;
      }

      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollableHeight = containerRef.current.offsetHeight - window.innerHeight;
      const triggerPoint = window.innerHeight * VIEWPORT_ANCHOR;

      if (totalScrollableHeight > 0) {
        const rawProgress = (triggerPoint - rect.top) / totalScrollableHeight;
        targetProgress.current = Math.max(0, Math.min(1, rawProgress));
      }
    };

    const animate = () => {
      currentProgress.current += (targetProgress.current - currentProgress.current) * LERP_FRICTION;
      const progress = currentProgress.current;

      const video = videoRef.current;
      if (video && isLoaded && !isSeeking.current && video.duration) {
        const targetTime = (video.duration - 0.05) * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.04) {
          isSeeking.current = true;
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const opacity = Math.max(0, 1 - (distance / 0.12));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        const yOffset = (progress - section.triggerTime) * 150;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      rafId = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    rafId = requestAnimationFrame(animate);

    // Initial check for scroll position
    handleScroll();

    return () => { 
      window.removeEventListener('scroll', handleScroll); 
      cancelAnimationFrame(rafId); 
    };
  }, [sections, isLoaded, layoutMode, scrollDepth, sensitivity]);

  const containerStyles = layoutMode === 'background' 
    ? { height: '350vh' } // Global mode simulation
    : { height: `${scrollDepth * 100}vh` };

  const stageClass = layoutMode === 'background' 
    ? "fixed inset-0 w-full h-full"
    : "sticky top-0 left-0 w-full h-screen";

  return (
    <div 
      ref={containerRef} 
      className="relative overflow-visible" 
      style={containerStyles}
    >
      <div className={`${stageClass} overflow-hidden z-0 bg-black`}>
        <video 
          ref={videoRef} 
          onSeeked={() => { isSeeking.current = false; }} 
          playsInline 
          muted 
          preload="auto" 
          className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
        />

        <div className="absolute inset-0 bg-gradient-to-b from-black via-transparent to-black opacity-70 pointer-events-none z-[5]" />

        {!isLoaded && (
          <div className="absolute inset-0 flex items-center justify-center z-20">
            <div className="w-12 h-12 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
          </div>
        )}

        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div 
              key={idx} 
              ref={(el) => { sectionRefs.current[idx] = el; }} 
              className="absolute w-full max-w-7xl mx-auto px-6 md:px-12" 
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-xl mx-auto space-y-6">
                  <div className="bg-black/80 backdrop-blur-2xl p-4 rounded-2xl border border-white/10 shadow-2xl space-y-3">
                    <div className="flex justify-between items-center">
                      <span className="text-[9px] font-black text-indigo-400 uppercase tracking-widest">Timing Offset</span>
                      <span className="text-[9px] font-bold text-white/40">{(section.triggerTime * 100).toFixed(0)}%</span>
                    </div>
                    <input 
                      type="range" min="0" max="1" step="0.01" value={section.triggerTime} 
                      onChange={(e) => onUpdateSection?.(idx, { ...section, triggerTime: parseFloat(e.target.value) })}
                      className="w-full accent-indigo-500 h-1.5 bg-white/10 rounded-full appearance-none cursor-pointer"
                    />
                  </div>
                  <input 
                    className="bg-black/90 backdrop-blur-3xl border-2 border-indigo-500/50 p-6 rounded-3xl outline-none text-2xl md:text-5xl font-black text-white w-full text-center tracking-tighter uppercase shadow-[0_30px_60px_rgba(0,0,0,0.8)]" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                </div>
              ) : (
                <div className="space-y-6">
                  <h2 className="text-5xl md:text-[10vw] font-black text-white leading-none uppercase tracking-tighter drop-shadow-[0_20px_60px_rgba(0,0,0,0.9)]">{section.title}</h2>
                  <p className="text-white/50 text-xs md:text-2xl max-w-3xl mx-auto font-black tracking-[0.4em] uppercase leading-relaxed">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

