import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
  layoutMode?: 'section' | 'background';
  scrollDepth: number;
  sensitivity: number;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  onUpdateSection, 
  isEditMode,
  layoutMode = 'section',
  scrollDepth,
  sensitivity
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);

  const LERP_FRICTION = sensitivity; 

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    setIsLoaded(false);
    video.src = videoUrl;
    video.load();

    const handleLoaded = () => {
      setIsLoaded(true);
      video.currentTime = 0.01; // Tiny offset to force frame render
    };

    video.addEventListener('loadedmetadata', handleLoaded);
    video.addEventListener('canplay', handleLoaded);

    return () => {
      video.removeEventListener('loadedmetadata', handleLoaded);
      video.removeEventListener('canplay', handleLoaded);
    };
  }, [videoUrl]);

  useEffect(() => {
    let rafId: number;

    const handleScroll = () => {
      if (layoutMode === 'background') {
        const totalHeight = document.documentElement.scrollHeight - window.innerHeight;
        const progress = window.scrollY / (totalHeight || 1);
        targetProgress.current = Math.max(0, Math.min(1, progress));
        return;
      }

      if (!containerRef.current) return;

      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollableHeight = containerRef.current.offsetHeight - window.innerHeight;

      if (totalScrollableHeight > 0) {
        // Correct progress calculation: 0 when top is at top of viewport, 1 when bottom is at bottom
        const rawProgress = -rect.top / totalScrollableHeight;
        targetProgress.current = Math.max(0, Math.min(1, rawProgress));
      }
    };

    const animate = () => {
      currentProgress.current += (targetProgress.current - currentProgress.current) * LERP_FRICTION;
      const progress = currentProgress.current;

      const video = videoRef.current;
      if (video && isLoaded && !isSeeking.current && video.duration > 0) {
        const targetTime = (video.duration - 0.1) * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.02) {
          isSeeking.current = true;
          video.currentTime = targetTime;
        }
      }

      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const opacity = Math.max(0, 1 - (distance / 0.12));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        const yOffset = (progress - section.triggerTime) * 120;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      rafId = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    rafId = requestAnimationFrame(animate);
    handleScroll();

    return () => { 
      window.removeEventListener('scroll', handleScroll); 
      cancelAnimationFrame(rafId); 
    };
  }, [sections, isLoaded, layoutMode, scrollDepth, sensitivity]);

  const containerStyles = layoutMode === 'background' 
    ? { height: '300vh' } 
    : { height: `${scrollDepth * 100}vh` };

  const stageClass = layoutMode === 'background' 
    ? "fixed inset-0 w-full h-full z-0"
    : "sticky top-0 left-0 w-full h-screen z-0";

  return (
    <div 
      ref={containerRef} 
      className="relative w-full overflow-visible" 
      style={containerStyles}
    >
      <div className={`${stageClass} overflow-hidden bg-black`}>
        <video 
          ref={videoRef} 
          onSeeked={() => { isSeeking.current = false; }} 
          playsInline 
          muted 
          preload="auto" 
          className={`w-full h-full object-cover transition-opacity duration-700 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
        />

        <div className="absolute inset-0 bg-gradient-to-b from-black via-transparent to-black opacity-60 pointer-events-none z-[5]" />

        {!isLoaded && (
          <div className="absolute inset-0 flex flex-col items-center justify-center z-20 gap-4">
            <div className="w-10 h-10 border-4 border-indigo-500 border-t-transparent rounded-full animate-spin" />
            <span className="text-[10px] font-black uppercase tracking-[0.4em] text-indigo-500/50">Waking Narrative Engine</span>
          </div>
        )}

        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none px-4 md:px-0">
          {sections.map((section, idx) => (
            <div 
              key={idx} 
              ref={(el) => { sectionRefs.current[idx] = el; }} 
              className="absolute w-full max-w-7xl mx-auto" 
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              {isEditMode ? (
                <div className="pointer-events-auto w-full max-w-xl mx-auto space-y-4 px-4">
                  <div className="bg-black/90 backdrop-blur-3xl p-6 rounded-[2rem] border border-white/10 shadow-2xl space-y-4">
                    <div className="flex justify-between items-center px-1">
                      <span className="text-[10px] font-black text-indigo-400 uppercase tracking-widest">Timing Offset</span>
                      <span className="text-[10px] font-bold text-white/50">{(section.triggerTime * 100).toFixed(0)}%</span>
                    </div>
                    <input 
                      type="range" min="0" max="1" step="0.001" value={section.triggerTime} 
                      onChange={(e) => onUpdateSection?.(idx, { ...section, triggerTime: parseFloat(e.target.value) })}
                      className="w-full accent-indigo-500 h-2 bg-white/5 rounded-full appearance-none cursor-pointer"
                    />
                  </div>
                  <input 
                    className="bg-black/95 backdrop-blur-3xl border-2 border-indigo-500/30 p-8 rounded-[2rem] outline-none text-2xl md:text-5xl font-black text-white w-full text-center tracking-tighter uppercase shadow-2xl focus:border-indigo-500 transition-all" 
                    value={section.title} 
                    onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })} 
                  />
                </div>
              ) : (
                <div className="space-y-6 md:space-y-10">
                  <h2 className="text-5xl md:text-[10vw] font-black text-white leading-[0.8] uppercase tracking-tighter drop-shadow-2xl">{section.title}</h2>
                  <p className="text-white/40 text-[10px] md:text-2xl max-w-5xl mx-auto font-black tracking-[0.5em] uppercase leading-relaxed drop-shadow-xl">{section.description}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default VideoScroller;

import React, { useState } from 'react';
import { Code, X, Edit3, Trash2, Check, Terminal, ChevronDown, Monitor, FileText, Smartphone } from 'lucide-react';
import FileUpload from './components/FileUpload';
import VideoScroller from './components/VideoScroller';
import InfinityLogo from './components/Logo';
import { generateVideoStory } from './services/geminiService';
import { generateSnippetCode } from './services/exportService';
import { VideoState, ScrollSection } from './types';

const SAMPLE_DATA: Record<string, ScrollSection[]> = {
  '1': [
    { title: "THE DREAM", description: "A voyage through the mechanical subconscious.", triggerTime: 0.15, alignment: 'center', vibe: 'cinematic' },
    { title: "SYNCHRONY", description: "Parts moving in a beautiful, unintended dance.", triggerTime: 0.35, alignment: 'left', vibe: 'cinematic' },
    { title: "NIGHTFALL", description: "Shadows defining the edges of the digital void.", triggerTime: 0.55, alignment: 'right', vibe: 'cinematic' },
    { title: "SYSTEMS", description: "Every gear turning with absolute purpose.", triggerTime: 0.75, alignment: 'center', vibe: 'cinematic' },
    { title: "INFINITY", description: "The loop continues beyond the frame.", triggerTime: 0.90, alignment: 'center', vibe: 'cinematic' }
  ]
};

const App: React.FC = () => {
  const [state, setState] = useState<VideoState>({
    url: null,
    duration: 0,
    sections: [],
    isAnalyzing: false,
    brandName: "INFINITY",
    sensitivity: 0.08,
    scrollDepth: 8,
    startOffset: 0.05,
    endOffset: 0.05,
    layoutMode: 'section',
    viewportAnchor: 0.1,
    widthMode: 'full',
    maxWidth: '1200px',
    topSpacer: 0,
    bottomSpacer: 100
  });

  const [isEditMode, setIsEditMode] = useState(false);
  const [showExportModal, setShowExportModal] = useState(false);
  const [copied, setCopied] = useState(false);

  const handleVideoInit = async (url: string, sourceName: string, sampleId?: string) => {
    const localData = sampleId ? SAMPLE_DATA[sampleId] : null;
    if (localData) {
      setState(prev => ({ ...prev, url, sections: localData, isAnalyzing: false }));
      return;
    }
    setState(prev => ({ ...prev, url, isAnalyzing: true }));
    try {
      const storySections = await generateVideoStory(`Source: ${sourceName}`, state.brandName);
      setState(prev => ({ ...prev, sections: storySections, isAnalyzing: false }));
    } catch (err) {
      setState(prev => ({ ...prev, sections: [], isAnalyzing: false }));
    }
  };

  if (state.url && !state.isAnalyzing) {
    return (
