import React, { useRef, useEffect, useState } from 'react';
import { ScrollSection } from '../types';

interface VideoScrollerProps {
  videoUrl: string;
  sections: ScrollSection[];
  onUpdateSection?: (index: number, section: ScrollSection) => void;
  isEditMode?: boolean;
  layoutMode?: 'section' | 'background';
  scrollDepth: number;
  sensitivity: number;
}

const VideoScroller: React.FC<VideoScrollerProps> = ({ 
  videoUrl, 
  sections, 
  onUpdateSection, 
  isEditMode,
  layoutMode = 'section',
  scrollDepth,
  sensitivity
}) => {
  const videoRef = useRef<HTMLVideoElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const sectionRefs = useRef<(HTMLDivElement | null)[]>([]);
  const [isLoaded, setIsLoaded] = useState(false);

  const targetProgress = useRef(0);
  const currentProgress = useRef(0);
  const isSeeking = useRef(false);
  const lastTargetTime = useRef(0);

  useEffect(() => {
    const video = videoRef.current;
    if (!video) return;

    setIsLoaded(false);
    video.src = videoUrl;
    video.load();

    const handleLoaded = () => {
      setIsLoaded(true);
      video.currentTime = 0.01; 
    };

    video.addEventListener('loadedmetadata', handleLoaded);
    return () => video.removeEventListener('loadedmetadata', handleLoaded);
  }, [videoUrl]);

  useEffect(() => {
    let rafId: number;

    const handleScroll = () => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      const totalScrollableHeight = containerRef.current.offsetHeight - window.innerHeight;

      if (totalScrollableHeight > 0) {
        // Linear progress calculation based on container top relative to viewport
        const rawProgress = -rect.top / totalScrollableHeight;
        targetProgress.current = Math.max(0, Math.min(1, rawProgress));
      }
    };

    const animate = () => {
      // Apply LERP for smooth transition
      currentProgress.current += (targetProgress.current - currentProgress.current) * sensitivity;
      const progress = currentProgress.current;

      const video = videoRef.current;
      // PERFORMANCE FIX: Only seek if not currently seeking and the difference is meaningful
      if (video && isLoaded && !video.seeking && video.duration > 0) {
        const targetTime = (video.duration - 0.1) * progress;
        if (Math.abs(video.currentTime - targetTime) > 0.03) {
          video.currentTime = targetTime;
        }
      }

      // Animate Narrative Nodes
      sections.forEach((section, idx) => {
        const el = sectionRefs.current[idx];
        if (!el) return;

        const distance = Math.abs(progress - section.triggerTime);
        const opacity = Math.max(0, 1 - (distance / 0.15));

        el.style.opacity = opacity.toString();
        el.style.visibility = opacity > 0.01 ? 'visible' : 'hidden';
        const yOffset = (progress - section.triggerTime) * -100;
        el.style.transform = `translate3d(0, ${yOffset}px, 0)`;
      });

      rafId = requestAnimationFrame(animate);
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    rafId = requestAnimationFrame(animate);
    handleScroll();

    return () => { 
      window.removeEventListener('scroll', handleScroll); 
      cancelAnimationFrame(rafId); 
    };
  }, [sections, isLoaded, layoutMode, scrollDepth, sensitivity]);

  // Height determines the "scroll runway"
  const containerStyles = { height: `${scrollDepth * 100}vh` };

  // Global Mode uses fixed, Section Mode uses sticky
  const stageClass = layoutMode === 'background' 
    ? "fixed inset-0 w-full h-full z-0"
    : "sticky top-0 left-0 w-full h-screen z-0";

  return (
    <div ref={containerRef} className="relative w-full" style={containerStyles}>
      <div className={`${stageClass} overflow-hidden bg-black`}>
        <video 
          ref={videoRef} 
          playsInline 
          muted 
          preload="auto" 
          className={`w-full h-full object-cover transition-opacity duration-1000 ${isLoaded ? 'opacity-100' : 'opacity-0'}`} 
        />
        <div className="absolute inset-0 bg-black/40 pointer-events-none z-[5]" />

        {/* The Narrative Layer */}
        <div className="absolute inset-0 z-10 flex items-center justify-center pointer-events-none">
          {sections.map((section, idx) => (
            <div 
              key={idx} 
              ref={(el) => { sectionRefs.current[idx] = el; }} 
              className="absolute w-full max-w-7xl mx-auto px-10" 
              style={{ opacity: 0, visibility: 'hidden', textAlign: section.alignment as any }}
            >
              <div className={`${isEditMode ? 'pointer-events-auto' : ''}`}>
                <h2 className="text-6xl md:text-[10vw] font-black text-white leading-[0.8] uppercase tracking-tighter drop-shadow-2xl">
                  {isEditMode ? (
                    <input 
                      className="bg-transparent border-b-2 border-indigo-500/50 outline-none w-full text-center"
                      value={section.title}
                      onChange={(e) => onUpdateSection?.(idx, { ...section, title: e.target.value })}
                    />
                  ) : section.title}
                </h2>
                <p className="mt-6 text-white/50 text-sm md:text-2xl font-black tracking-[0.4em] uppercase max-w-4xl mx-auto leading-relaxed">
                  {section.description}
                </p>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* Global Mode Simulation: Actual content scrolling over the fixed video */}
      {layoutMode === 'background' && !isEditMode && (
        <div className="relative z-20 pointer-events-none pt-[100vh]">
          <div className="max-w-4xl mx-auto px-10 space-y-[80vh] pb-[100vh]">
            <div className="space-y-6 opacity-30">
               <div className="h-1 w-20 bg-indigo-500"></div>
               <h3 className="text-4xl font-black uppercase tracking-tighter">Your Site Content</h3>
               <p className="text-xl font-medium leading-relaxed">This is a simulation of your website content scrolling over the fixed background. In Global Mode, the video remains stationary in the viewport while your elements glide over the narrative nodes.</p>
            </div>
            <div className="space-y-6 opacity-30 text-right">
               <h3 className="text-4xl font-black uppercase tracking-tighter">Immersive Depth</h3>
               <p className="text-xl font-medium leading-relaxed">The parallax effect created between your content and the background video provides an elite, premium feel used by top-tier digital agencies.</p>
            </div>
            <div className="space-y-6 opacity-30">
               <h3 className="text-4xl font-black uppercase tracking-tighter">Infinite Possibility</h3>
               <p className="text-xl font-medium leading-relaxed">Aeon Studio ensures that the technical complexity of scroll-syncing is handled, leaving you to focus on the narrative.</p>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

